public class StringUtil {
    public static class KeyVal {
        private String key;
        private String value;

        public KeyVal(String key, String value) {
            this.key = key;
            this.value = value;
        }

        public String getKey() {
            return key;
        }

        public String getValue() {
            return value;
        }
    }

    public static boolean contains(String str, String pattern) {
        return str.contains(pattern);
    }

    public static class URL {
        private String scheme;
        private String host;
        private int port;
        private String path;

        public URL(String url) {
            this.scheme = getScheme(url);
            this.host = getHost(url);
            this.port = getPort(url);
            this.path = getPath(url);
        }

        private static String getScheme(String url) {
            return url.split(":")[0];
        }

        private static String getHost(String url) {
            return url.split("//")[-1].split("/")[0];
        }

        private static int getPort(String url) {
            String[] parts = url.split(":");
            if (parts.length > 1) {
                return Integer.parseInt(parts[1]);
            }
            return -1;
        }

        private static String getPath(String url) {
            return url.split("/")[url.split("/").length - 1];
        }

        public String getScheme() {
            return scheme;
        }

        public String getHost() {
            return host;
        }

        public int getPort() {
            return port;
        }

        public String getPath() {
            return path;
        }
    }

    public static class UrlBuilder {
        private URL url;

        public UrlBuilder(URL url) {
            this.url = url;
        }

        public void setScheme(String scheme) {
            url.scheme = scheme;
        }

        public void setHost(String host) {
            url.host = host;
        }

        public void setPort(int port) {
            url.port = port;
        }

        public void setPath(String path) {
            url.path = path;
        }

        public URL build() {
            return new URL(url.toString());
        }
    }

    public static class KeyValHelper {
        public static boolean equals(KeyVal other, KeyVal keyVal) {
            return Objects.equals(keyVal.getKey(), other.key) && Objects.equals(keyVal.getValue(), other.value);
        }

        public static String hash(KeyVal keyVal) {
            return Objects.hash(keyVal.getKey(), keyVal.getValue());
        }
    }
}
